import os, re

def load_grids():
    d = os.environ['RLM_SESSION_DIR']
    t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')
    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows = [r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
            G[k] = [[int(x) for x in r] for r in rows]
    return G

G = load_grids()

def count_values(grid):
    counts = {}
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            v = grid[r][c]
            counts[v] = counts.get(v, 0) + 1
    return sorted(counts.items(), key=lambda x: -x[1])

def get_bg_and_marker(grid):
    bg = grid[0][0]
    counts = {v: 0 for v in range(10)}
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            v = grid[r][c]
            counts[v] += 1

    # Most common non-bg
    max_count = 0
    marker = None
    for v in range(10):
        if v != bg and counts[v] > max_count:
            max_count = counts[v]
            marker = v
    return bg, marker, counts

bg1, marker1, counts1 = get_bg_and_marker(G['Demo pair 1 input'])
print(f"Demo 1: bg={bg1}, marker={marker1}, marker_count={counts1.get(marker1, 0)}")

bg_test, marker_test, counts_test = get_bg_and_marker(G['Test input'])
print(f"Test: bg={bg_test}, marker={marker_test}, marker_count={counts_test.get(marker_test, 0)}")

# Now apply transformation
def transform_grid(grid):
    bg, marker, _ = get_bg_and_marker(grid)
    rows = len(grid)
    cols = len(grid[0])

    new_grid = [[grid[r][c] for c in range(cols)] for r in range(rows)]

    pattern = [4, 4, 0, 0, 0]

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == marker:
                # Place pattern starting at c-2
                for offset, pval in enumerate(pattern):
                    nc = c - 2 + offset
                    if 0 <= nc < cols:
                        new_grid[r][nc] = pval

    return new_grid

