    neighbors_same = 0
    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
            if grid[nr][nc] == target_val:
                neighbors_same += 1
    return neighbors_same

def is_isolated_marker(grid, r, c):
