        row_placements = sorted(by_row[r])
        # Check for overlaps
        max_end = -1
        for nc, v in row_placements:
            start = nc - 2
            end = nc + 2  # inclusive
            if start > max_end:
                # No overlap with previous, fill this whole pattern
                for offset in range(5):
                    target = nc - 2 + offset
                    if 0 <= target < cols:
                        new_grid[r][target] = v
                max_end = end

            elif start <= max_end:
