        # Group consecutive ones
        groups = []
        if isolated:
            curr = [isolated[0]]
            for i in range(1, len(isolated)):
                if isolated[i] == isolated[i-1] + 1:
                    curr.append(isolated[i])
                else:
                    groups.append(curr)
                    curr = [isolated[i]]
            groups.append(curr)

